class Animal:
    def __init__(self, name, sound):
        self.name  = name
        self.sound = sound

    def speak(self):
        return f"{self.name} says {self.sound}"

    def __str__(self):
        return f"Animal({self.name})"

class Dog(Animal):              # Dog IS-A Animal
    def __init__(self, name):
        super().__init__(name, "Woof")   # call parent __init__
        self.tricks = []

    def learn_trick(self, trick):
        self.tricks.append(trick)

    def speak(self):            # METHOD OVERRIDING
        return f"{self.name} barks: Woof! Woof!"

class Cat(Animal):
    def __init__(self, name):
        super().__init__(name, "Meow")

d = Dog("Rex")
d.learn_trick("sit")
print(d.speak())               # Rex barks: Woof! Woof!
print(d.tricks)                # ['sit']
print(isinstance(d, Animal))  # True
print(isinstance(d, Dog))     # True

class A:
    def hello(self):
        return "Hello from A"

class B(A):
    def hello(self):
        return "Hello from B"

class C(A):
    def hello(self):
        return "Hello from C"

class D(B, C):                # Multiple inheritance
    pass

d = D()
print(d.hello())              # Hello from B  (MRO: D→B→C→A)
print(D.__mro__)              # (<class 'D'>,<class 'B'>,<class 'C'>,<class 'A'>,...)
print(issubclass(D, A))      # True

class BankAccount:
    def __init__(self, owner, balance):
        self.owner    = owner        # public
        self._branch  = "Main"       # protected (convention)
        self.__balance = balance      # private (name mangled)

    def deposit(self, amount):
        if amount > 0:
            self.__balance += amount

    def withdraw(self, amount):
        if 0 < amount <= self.__balance:
            self.__balance -= amount
        else:
            print("Insufficient funds")

    def get_balance(self):           # getter
        return self.__balance

acc = BankAccount("Alice", 1000)
acc.deposit(500)
print(acc.get_balance())      # 1500
print(acc.owner)              # Alice  (public)
print(acc._branch)            # Main   (protected — accessible but discouraged)
# print(acc.__balance)        # AttributeError!
print(acc._BankAccount__balance)  # 1500  (name mangling)

class Temperature:
    def __init__(self, celsius):
        self._celsius = celsius

    @property
    def celsius(self):              # getter
        return self._celsius

    @celsius.setter
    def celsius(self, value):       # setter with validation
        if value < -273.15:
            raise ValueError("Temperature below absolute zero!")
        self._celsius = value

    @property
    def fahrenheit(self):           # computed property
        return self._celsius * 9/5 + 32

t = Temperature(25)
print(t.celsius)        # 25      (calls getter)
print(t.fahrenheit)     # 77.0   (computed)
t.celsius = 100         # calls setter
print(t.fahrenheit)     # 212.0
# t.celsius = -300      # ValueError!

class Shape:
    def area(self):
        raise NotImplementedError("Subclass must implement area()")

    def describe(self):
        return f"I am a {type(self).__name__} with area {self.area():.2f}"

class Circle(Shape):
    def __init__(self, r):
        self.r = r
    def area(self):              # override
        return 3.14159 * self.r ** 2

class Rectangle(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h
    def area(self):              # override
        return self.w * self.h

class Triangle(Shape):
    def __init__(self, b, h):
        self.b, self.h = b, h
    def area(self):              # override
        return 0.5 * self.b * self.h

# Polymorphic behaviour — same call, different results
shapes = [Circle(5), Rectangle(4, 6), Triangle(3, 8)]
for s in shapes:
    print(s.describe())
# I am a Circle with area 78.54
# I am a Rectangle with area 24.00
# I am a Triangle with area 12.00

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):          # v1 + v2
        return Vector(self.x + other.x, self.y + other.y)

    def __sub__(self, other):          # v1 - v2
        return Vector(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):         # v * 3
        return Vector(self.x * scalar, self.y * scalar)

    def __len__(self):                 # len(v)
        return int((self.x**2 + self.y**2) ** 0.5)

    def __eq__(self, other):           # v1 == v2
        return self.x == other.x and self.y == other.y

    def __str__(self):
        return f"Vector({self.x}, {self.y})"

v1 = Vector(2, 3)
v2 = Vector(1, 4)
print(v1 + v2)     # Vector(3, 7)
print(v1 - v2)     # Vector(1, -1)
print(v1 * 3)      # Vector(6, 9)
print(len(v1))     # 3
print(v1 == v2)    # False

from abc import ABC, abstractmethod

class Animal(ABC):             # abstract class
    @abstractmethod
    def speak(self):           # must be implemented by subclasses
        pass

    @abstractmethod
    def move(self):
        pass

class Dog(Animal):
    def speak(self):
        return "Woof!"
    def move(self):
        return "Runs on four legs"

class Bird(Animal):
    def speak(self):
        return "Tweet!"
    def move(self):
        return "Flies with wings"

# Animal()   # TypeError — cannot instantiate abstract class
d = Dog()
b = Bird()
for animal in [d, b]:
    print(animal.speak(), "|", animal.move())

class Stack:
    def __init__(self):
        self._data = []

    def push(self, item):
        self._data.append(item)

    def pop(self):
        if self._data:
            return self._data.pop()
        raise IndexError("Stack is empty")

    def __len__(self):              # len(stack)
        return len(self._data)

    def __str__(self):              # print(stack)
        return f"Stack{self._data}"

    def __repr__(self):
        return f"Stack({self._data!r})"

    def __contains__(self, item):   # item in stack
        return item in self._data

    def __getitem__(self, index):   # stack[index]
        return self._data[index]

s = Stack()
s.push(1); s.push(2); s.push(3)
print(len(s))        # 3
print(s)             # Stack[1, 2, 3]
print(2 in s)        # True
print(s[0])          # 1
print(s.pop())       # 3

class Date:
    def __init__(self, day, month, year):
        self.day   = day
        self.month = month
        self.year  = year

    def display(self):                      # instance method
        return f"{self.day:02d}/{self.month:02d}/{self.year}"

    @classmethod
    def from_string(cls, date_str):         # class method — factory
        day, month, year = map(int, date_str.split('-'))
        return cls(day, month, year)

    @classmethod
    def today(cls):                         # another factory
        import datetime
        d = datetime.date.today()
        return cls(d.day, d.month, d.year)

    @staticmethod
    def is_leap_year(year):                 # static utility
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

d1 = Date(15, 8, 2024)
print(d1.display())                  # 15/08/2024

d2 = Date.from_string('25-12-2025')  # factory constructor
print(d2.display())                  # 25/12/2025

print(Date.is_leap_year(2024))       # True
print(Date.is_leap_year(2023))       # False
